#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Cloudflare setup for issues #3 (mail path), #8 (tunnel and Access) and #9
# (Backups). Runbooks: docs/provisioning.md and docs/pi-deployment.md.
#
# Non-secret settings go to deploy/admin.env (ignored by git), to copy to the
# Pi as /etc/private-profile/admin.env. Tokens never pass through this script:
# they go from Cloudflare to the Owner's password manager, then to the Pi.
# The one exception is `restic init`, which gets the R2 key pair in its
# environment and nowhere else; nothing is saved.

cd "$(git rev-parse --show-toplevel)"
ENV_FILE=deploy/admin.env
WRANGLER_CONFIG=apps/email-worker/wrangler.jsonc
SEED_LOCAL_PART=seed-test
BACKUP_BUCKET=private-profile-backups

wrangler() { pnpm --dir apps/email-worker exec wrangler "$@"; }

# ask_until KEY "Prompt" REGEX "Hint" asks until the value matches REGEX.
ask_until() {
  local key="$1" prompt="$2" regex="$3" hint="$4"
  while true; do
    ask "$key" "$prompt"
    [[ "${!key}" =~ $regex ]] && return
    warn "$hint"
  done
}

# check_mail "Send to" "Expected" asks whether a test mail behaved as expected.
check_mail() {
  # No full stop after the address, so copying the line doesn't pick one up.
  step "Send a mail from the outside account to: ${BOLD}$1${RESET}"
  note "Expected: $2"
  if ! confirm "Did that happen?"; then
    SKIPPED+=("Mail to $1 didn't behave as expected; check Email Routing > Activity log")
    warn "Check Email Routing > Activity log for what Cloudflare did with it."
  fi
}

run_wizard() {

TOTAL_STAGES=13

[[ -f "$ENV_FILE" ]] || (umask 077 && cp deploy/admin.env.example "$ENV_FILE")

banner "Cloudflare setup for Private Profile"

stage "Register the Profile Domain"
say "A new, unremarkable domain used for nothing else. Nothing in it should"
say "hint at your name, location or other domains."
open_url "https://dash.cloudflare.com"
step "Go to Domain Registration > Register Domains, search, and buy the domain."
note "Another registrar works too: turn on WHOIS privacy, add the domain to"
note "Cloudflare and switch to the two nameservers Cloudflare gives you."
step "Wait until the dashboard lists the domain as Active."
pause "Press Enter once it shows Active."
ask_until PROFILE_DOMAIN "Profile Domain (such as profile.example):" \
  '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$' \
  "Lowercase domain only, no https:// or trailing dot."
write_env PROFILE_DOMAIN "$PROFILE_DOMAIN"

stage "Turn on Email Routing"
open_url "https://developers.cloudflare.com/email-routing/get-started/enable-email-routing/"
step "In the dashboard, open $PROFILE_DOMAIN > Email > Email Routing and enable it."
step "Remove any other MX records first, then let Cloudflare add its MX and SPF records."
pause "Press Enter once Email Routing reports the DNS records as configured."
if command -v dig >/dev/null 2>&1; then
  mx=$(dig +short MX "$PROFILE_DOMAIN" | awk '{print $2}')
  say "MX records now: ${mx:-none yet}"
  if [[ -z "$mx" ]] || grep -qv 'mx\.cloudflare\.net\.$' <<<"$mx"; then
    warn "Expected only *.mx.cloudflare.net hosts. DNS can take a few minutes."
    SKIPPED+=("Check that dig +short MX $PROFILE_DOMAIN lists only *.mx.cloudflare.net")
  fi
else
  SKIPPED+=("Check that dig +short MX $PROFILE_DOMAIN lists only *.mx.cloudflare.net")
fi
pause

stage "Verify the Personal Inbox"
say "Workers can only forward to verified destination addresses."
step "On the Email Routing page, open Destination addresses and add your Personal Inbox."
step "Click the link in the verification mail Cloudflare sends to it."
pause "Press Enter once it shows Verified."

stage "Create the KV namespace"
say "Signing wrangler in to your Cloudflare account (a browser tab opens)."
wrangler login
wrangler whoami
ask_until CLOUDFLARE_ACCOUNT_ID "Account ID from the table above:" '^[0-9a-f]{32}$' \
  "An account ID is 32 lowercase hex characters."
write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
if [[ -n "$(_existing KV_NAMESPACE_ID || true)" ]] && ! confirm "A KV namespace ID is already saved. Create a new namespace anyway?"; then
  KV_NAMESPACE_ID=$(_existing KV_NAMESPACE_ID)
else
  wrangler kv namespace create PROFILE_ADDRESSES
  ask_until KV_NAMESPACE_ID "The namespace id printed above:" '^[0-9a-f]{32}$' \
    "A namespace id is 32 lowercase hex characters."
fi
write_env KV_NAMESPACE_ID "$KV_NAMESPACE_ID"
sed -i.bak -E "s/(\"id\": \")[^\"]*(\")/\1$KV_NAMESPACE_ID\2/" "$WRANGLER_CONFIG" && rm -f "$WRANGLER_CONFIG.bak"
printf '  %s✓ wrote%s KV namespace id → %s\n' "$GREEN" "$RESET" "$WRANGLER_CONFIG"
note "The id isn't secret: commit $WRANGLER_CONFIG on a feature branch afterwards."
pause

stage "Deploy the Worker"
pnpm --dir apps/email-worker run deploy
say "Now set the Personal Inbox as a Worker secret. Type it at wrangler's"
say "prompt: it goes only into the secret, never into git or this script."
wrangler secret put PERSONAL_INBOX
wrangler secret list
pause "Press Enter if PERSONAL_INBOX is listed above."

stage "Route all mail to the Worker"
open_url "https://developers.cloudflare.com/email-routing/email-workers/enable-email-workers/"
step "In Email Routing > Routing rules, edit the Catch-all address."
step "Set the action to Send to a Worker, pick private-profile-email, and save."
step "Then switch the catch-all's status toggle to Enabled. It's off by default."
warn "Don't add per-address rules: the Worker and KV make every decision."
pause "Press Enter once the catch-all is enabled."

stage "Send real mail"
seed="$SEED_LOCAL_PART@$PROFILE_DOMAIN"
wrangler kv key put --binding PROFILE_ADDRESSES --remote "$seed" live
say "Seeded $seed as live. KV takes about a minute to reach the Worker."
pause "Wait a minute, then press Enter."
say "Send from an outside account, not the Personal Inbox (Gmail hides mail to yourself)."
check_mail "$seed" "arrives in the Personal Inbox; Show original has X-Profile-Address."
check_mail "never-issued@$PROFILE_DOMAIN" "the sender gets a permanent (5xx) bounce; nothing arrives."
check_mail "postmaster@$PROFILE_DOMAIN" "arrives in the Personal Inbox, without X-Profile-Address."
pause

stage "Delete the test address"
say "So it never looks like an issued Profile Address."
wrangler kv key delete --binding PROFILE_ADDRESSES --remote "$seed" ||
  warn "Couldn't delete it. The admin app's first reconcile removes it anyway."
note "Then set up the Gmail filter from the README (Labelling Profile mail in Gmail)."
pause

stage "Create the admin app's API token"
say "The admin app writes, lists and deletes KV keys to mirror the Profiles."
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Create Token > Create Custom Token, named private-profile-admin."
step "Permissions: Account > Workers KV Storage > Edit."
step "Account Resources: Include > your account only."
step "Create it and save the token in your password manager."
warn "Don't paste it here. It goes on the Pi as /etc/private-profile/cloudflare-api-token."
pause "Press Enter once it's in your password manager."

stage "Create the tunnel"
say "A subdomain of the Profile Domain works. Make it hard to guess: scanners try"
say "admin, login, dash and the like first. A domain of your own also works."
ask ADMIN_HOSTNAME "Admin hostname (such as stash.$PROFILE_DOMAIN):"
while [[ "$ADMIN_HOSTNAME" == "$PROFILE_DOMAIN" || "$ADMIN_HOSTNAME" != *.* ]]; do
  warn "Use a subdomain, not the Profile Domain itself, which only receives mail."
  ask ADMIN_HOSTNAME "Admin hostname:"
done
open_url "https://one.dash.cloudflare.com"
note "If asked, activate the Zero Trust Free plan. Keep the team name bland:"
note "it shows on the sign-in page."
step "Go to Networks > Tunnels and create a cloudflared tunnel named private-profile."
step "For the environment, pick Docker and copy only the token after --token into"
step "your password manager. Don't run the command."
note "If Continue stays greyed out, go back to Tunnels: the tunnel already exists."
step "Open the tunnel > Routes > add a Published application route:"
step "$ADMIN_HOSTNAME, service URL http://admin:8080."
warn "Don't paste the token here. It goes on the Pi as /etc/private-profile/tunnel-token."
pause "Press Enter once the hostname is added."

stage "Protect it with Access"
step "In Zero Trust, go to Access > Applications and add a Self-hosted application for $ADMIN_HOSTNAME."
step "Add one Allow policy whose only Include rule is Emails equal to your email."
note "The AUD tag is on the application's Additional settings tab, or its row in"
note "the Applications list."
ask_until ACCESS_AUD "The application's Application Audience (AUD) tag:" '^[0-9a-f]{32,128}$' \
  "An AUD tag is a long string of lowercase hex characters."
write_env ACCESS_AUD "$ACCESS_AUD"
step "Find your team domain under Account details on the Zero Trust Overview."
ask_until ACCESS_TEAM_DOMAIN "Team domain (such as owner.cloudflareaccess.com):" \
  '^[a-z0-9-]+\.cloudflareaccess\.com$' "Just <team>.cloudflareaccess.com, no https://."
write_env ACCESS_TEAM_DOMAIN "$ACCESS_TEAM_DOMAIN"
pause

stage "Create the Backup bucket"
say "Each Backup is stored as a restic snapshot of the Profile database in R2,"
say "encrypted on the Pi before upload (docs/adr/0003)."
open_url "https://dash.cloudflare.com"
step "Go to R2 Object Storage > Create bucket, named $BACKUP_BUCKET. Keep the defaults."
step "Back on R2 Object Storage, open Manage API tokens > Create Account API token,"
step "named private-profile-backups."
step "Permissions: Object Read & Write. Apply to specific buckets only: $BACKUP_BUCKET."
step "Create it and save the Access Key ID and Secret Access Key in your password manager."
step "In your password manager, also generate a long random restic password."
warn "Without the restic password the Backups can't be read. Keep it only in the"
warn "password manager and on the Pi."
write_env RESTIC_REPOSITORY "s3:https://$CLOUDFLARE_ACCOUNT_ID.r2.cloudflarestorage.com/$BACKUP_BUCKET"
pause "Press Enter once all three are in your password manager."

stage "Create the restic repository"
say "The admin app never creates the repository, so a wrong setting can't start"
say "a second, empty one."
if command -v restic >/dev/null 2>&1; then
  say "Paste the R2 key pair from your password manager. It goes only to restic."
  ask_secret R2_ACCESS_KEY_ID "R2 Access Key ID:"
  ask_secret R2_SECRET_ACCESS_KEY "R2 Secret Access Key:"
  say "restic now asks for the restic password twice. Paste it from your password manager."
  if AWS_ACCESS_KEY_ID="$R2_ACCESS_KEY_ID" AWS_SECRET_ACCESS_KEY="$R2_SECRET_ACCESS_KEY" \
    restic --repo "$RESTIC_REPOSITORY" init; then
    printf '  %s✓ created%s the restic repository\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("restic init failed: create the repository on the Pi (docs/pi-deployment.md step 7)")
  fi
  unset R2_ACCESS_KEY_ID R2_SECRET_ACCESS_KEY
else
  SKIPPED+=("restic isn't installed here: create the repository on the Pi (docs/pi-deployment.md step 7)")
  warn "restic isn't installed here. Create the repository on the Pi instead (docs/pi-deployment.md step 7)."
fi
say "Next: copy $ENV_FILE to the Pi and follow docs/pi-deployment.md from step 5."
pause

finish
}

run_wizard "$@"; exit
